def minimum_length_encoding_brute(words):
    words = list(set(words))
    total = 0
    for i, w in enumerate(words):
        needed = True
        for j, other in enumerate(words):
            if i != j and other.endswith(w) and len(other) > len(w):    # w is a suffix of a longer word
                needed = False
                break
        if needed:
            total += len(w) + 1
    return total

