def minimum_length_encoding(words):
    word_set = set(words)
    for w in words:
        for i in range(1, len(w)):
            word_set.discard(w[i:])                        # remove every proper suffix
    return sum(len(w) + 1 for w in word_set)                # survivors contribute length+1 each

