import java.util.*;

public class Main {
    static int minimumLengthEncoding(String[] words) {
        Set<String> wordSet = new HashSet<>(Arrays.asList(words));
        for (String w : words) {
            for (int i = 1; i < w.length(); i++) wordSet.remove(w.substring(i));  // remove every proper suffix
        }
        int total = 0;
        for (String w : wordSet) total += w.length() + 1;          // survivors contribute length+1 each
        return total;
    }
}

