#include <bits/stdc++.h>
using namespace std;

int minimumLengthEncoding(vector<string>& words) {
    unordered_set<string> wordSet(words.begin(), words.end());
    for (auto& w : words) {
        for (int i = 1; i < (int)w.size(); i++) wordSet.erase(w.substr(i));     // remove every proper suffix
    }
    int total = 0;
    for (auto& w : wordSet) total += w.size() + 1;              // survivors contribute length+1 each
    return total;
}
